"""Inspect retained primary positioner sources; preserve uncertain conference identity."""
import ledger as L
from review_batch_0001 import evidence

def main():
 base=L.ROOT/'assets/research-20261105';doi='10.1038/nnano.2015.240'
 ev=evidence(base/'funke-positioner-2015.html','https://www.nature.com/articles/nnano.2015.240','Publisher abstract, authors and publication/issue dates; full article is subscription preview')
 si=evidence(base/'funke-positioner-2015-si.pdf','https://static-content.springer.com/esm/art%3A10.1038%2Fnnano.2015.240/MediaObjects/41565_2016_BFnnano2015240_MOESM9_ESM.pdf','PDF pp2–5 Methods/model, p15 Fig2 diagram caption, p16 Fig3 text and rendered image, pp17–19 characterization, pp31–32 Tables1–2')
 q=['Verify complete core and adjuster oligonucleotide sets from routing diagram/native sources; no sequence completeness claim from text extraction.','Map length, adjuster multiplicity and fluorophore/thiol mounting variants without counting reported123 displacements as123 independent cores.','Inspect full article and remaining SI sections; PDF extraction reports invalid-font-weight warnings.','Confirm conference relationship using abstract/full presentation; matching authors and related title alone do not establish identity.']
 p=next(p for p in L.read('publication_reviews') if p['registry_key']==doi)
 p.update(title='Placing molecules with Bohr radius resolution using DNA origami',authors=['Jonas J. Funke','Hendrik Dietz'],review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['new_design','modified_design'],catalog_eligibility='unresolved',access='partial',rationale='Primary SI identifies a p7704-scaffold positioning apparatus. Fig3 distinguishes four2nt hinge connectors from four30nt loose loops, with up to four orthogonal duplex adjusters. Three-adjuster objects with10–50bp lengths are characterized in Fig6/Table1. Table2 distinguishes three thiol mounting-site geometries. Routing/sequence completeness and lattice eligibility remain unverified.',date_evidence={'date':'2015-10-19','source':ev,'primary_verified':True,'meaning':'Publisher online publication date'},date_events=[{'date':'2016-01','meaning':'Issue date','source':ev}],evidence=[ev,si],unresolved_questions=q,reviewer='Codex primary supplement section and Fig3 image inspection',run_id='DISC0005-positioner',date=L.DATE)
 L.upsert('publication_reviews',p,'Separate online date and issue date; record inspectable design-source evidence')
 d=dict(design_id='RDE0013',publication_keys=[doi],named_objects=['Hinged molecular positioner and adjuster/mounting variants'],core_variant_composition='p7704 core; top arm helices0–23 and bottom28–51 in Fig3. Four2nt tight hinge connectors and four30nt loose loops. Up to four orthogonal adjuster duplexes; three-adjuster10–50bp series characterized. Fluorescence and thiol mounting variants remain to be fully mapped.',lattice_decision='unresolved',catalog_eligibility='unresolved',source_completeness='not_verified',source_files=[ev,si],evidence=[ev,si],outstanding_checks=q,relationships=[],variant_links=[],legacy_record={},review_run='DISC0005-positioner',date=L.DATE)
 old=next((x for x in L.read('design_evidence') if x['design_id']==d['design_id']),None);assert old is None or old['publication_keys']==[doi]
 L.upsert('design_evidence',d,'Keep design family distinct from configuration measurements')
 c=next(p for p in L.read('publication_reviews') if p['registry_key']=='conference:fnano2015:ea4e384c138f33');c.update(authors=['Jonas Funke','Hendrik Dietz'],full_author_list_transcribed=True)
 L.upsert('publication_reviews',c,'Transcribe both authors printed on schedule p8')
 L.upsert('discovery_edges',dict(edge_id='possible_journal_counterpart:'+c['registry_key']+':'+doi,source_key=c['registry_key'],target_key=doi,relation='possible_journal_counterpart',evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator='Publisher title/authors compared with FNANO2015 p8; conference abstract pending',reconciliation_state='pending_exact_design_or_version_confirmation',run_id='DISC0005-positioner',date=L.DATE),'Do not merge conference and journal work identities')
 b=next(b for b in L.read('batches') if b['batch_id']=='DISC0005')
 action='Reviewed positioner publisher metadata and SI Methods, Fig2/3/6, Tables1/2; recorded RDE0013 and tentative FNANO2015 counterpart.'
 if action not in b['completed_actions']:b['completed_actions'].append(action)
 if doi not in b['input_keys']:b['input_keys'].append(doi)
 if doi not in b['unresolved_keys']:b['unresolved_keys'].append(doi)
 b.update(after_counts=L.counts(),validation=[L.validate()],next_queue=['Enumerate all Dietz lab bibliography entries and follow pre2010 page; retained main HTML awaiting extraction.','Extract all33 positioner main references without keyword filtering; inspect remaining SI and native design availability.','Continue FNANO2014 schedule and abstract/counterpart reconciliation for2015–2019.','Resume broad/low-keyword screening and source follow-up.']);L.upsert('batches',b,'Save positioner review and next queue');print(L.validate())
